        // === 1-45: AYETLER VE HADİS-İ ŞERİFLER (İlim & Hikmet) ===
        MotivationQuote(1, "De ki: Hiç bilenlerle bilmeyenler bir olur mu?", "Zümer Suresi, 9", QuoteCategory.AYET_HADIS),
        MotivationQuote(2, "Rabbim, benim ilmimi artır!", "Tâhâ Suresi, 114", QuoteCategory.AYET_HADIS),
        MotivationQuote(3, "Allah, içinizden iman edenlerin ve kendilerine ilim verilenlerin derecelerini yükseltir.", "Mücadele Suresi, 11", QuoteCategory.AYET_HADIS),
