        MotivationQuote(8, "İlim talep etmek her Müslümana farzdır.", "Hadis-i Şerif (İbn Mâce)", QuoteCategory.AYET_HADIS),
        MotivationQuote(9, "Kim ilim tahsil etmek için bir yola girerse, Allah ona cennetin yolunu kolaylaştırır.", "Hadis-i Şerif (Müslim)", QuoteCategory.AYET_HADIS),
