        MotivationQuote(15, "İlim Çin'de de olsa onu arayınız.", "Hadis-i Şerif (Beyhakî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(16, "Ya alim ol, ya öğrenci ol, ya dinleyen ol, ya da ilmi seven ol; beşincisi olma helak olursun!", "Hadis-i Şerif (Beyhakî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(17, "İnsan ölünce üç ameli hariç ameli kesilir: Sadaka-i cariye, faydalanılan ilim ve dua eden salih evlat.", "Hadis-i Şerif (Müslim)", QuoteCategory.AYET_HADIS),
        MotivationQuote(18, "Melekler, ilim talibinin yaptığı işten hoşnut olarak kanatlarını onun altına sererler.", "Hadis-i Şerif (Ahmed b. Hanbel)", QuoteCategory.AYET_HADIS),
        MotivationQuote(19, "Sudaki balıklara varıncaya kadar her şey, alim için istiğfar eder.", "Hadis-i Şerif (Ebû Dâvûd)", QuoteCategory.AYET_HADIS),
        MotivationQuote(20, "Alimin abide üstünlüğü, dolunayın diğer yıldızlara üstünlüğü gibidir.", "Hadis-i Şerif (Tirmizî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(21, "İki kimseye gıpta edilir: Biri Allah'ın kendisine mal verip hak yolunda harcayan, diğeri ilim verip onunla hükmeden ve öğreten.", "Hadis-i Şerif (Buhârî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(22, "İlim servetten hayırlıdır; çünkü ilim seni korur, serveti ise sen korursun.", "Hz. Ali (k.v.)", QuoteCategory.AYET_HADIS),
        MotivationQuote(23, "İlmi yazı ile bağlayıp kaydediniz.", "Hadis-i Şerif (Dârimî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(24, "Allah bir kuluna hayır dilerse, onu dinde fakih (derin anlayış sahibi) kılar.", "Hadis-i Şerif (Buhârî, Müslim)", QuoteCategory.AYET_HADIS),
        MotivationQuote(25, "Faydasız ilimden, korkmayan kalpten ve kabul olmayan duadan Allah'a sığınırım.", "Hadis-i Şerif (Müslim)", QuoteCategory.AYET_HADIS),
        MotivationQuote(26, "İlim amel etmek içindir; amel ise kurtuluş içindir.", "Kelâm-ı Kibar", QuoteCategory.AYET_HADIS),
        MotivationQuote(27, "Bilen bir kavim için ayetleri ayrıntılı olarak açıkladık.", "En'âm Suresi, 98", QuoteCategory.AYET_HADIS),
        MotivationQuote(28, "Şüphesiz bunda akleden bir topluluk için ibretler vardır.", "Nahl Suresi, 12", QuoteCategory.AYET_HADIS),
        MotivationQuote(29, "Sözü dinleyip de onun en güzeline uyanlar... İşte onlar akıl sahipleridir.", "Zümer Suresi, 18", QuoteCategory.AYET_HADIS),
        MotivationQuote(30, "Yeryüzünde gezip dolaşmıyorlar mı ki, düşünecek kalpleri olsun?", "Hac Suresi, 46", QuoteCategory.AYET_HADIS),
        MotivationQuote(31, "Sadaka malı eksiltmez; ilim paylaşıldıkça bereketlenir ve çoğalır.", "Rivayet / Hadis İzahı", QuoteCategory.AYET_HADIS),
        MotivationQuote(32, "Kendisine sorulan ilmi gizleyen kimseye kıyamet günü ateşten bir gem vurulur.", "Hadis-i Şerif (Ebû Dâvûd)", QuoteCategory.AYET_HADIS),
        MotivationQuote(33, "Kıyamet günü alimlerin mürekkebi şehitlerin kanıyla tartılır.", "Rivayet / İbn Abdilberr", QuoteCategory.AYET_HADIS),
        MotivationQuote(34, "İlim hazinedir, anahtarı ise sual sormaktır.", "Hadis-i Şerif (Ebû Nuaym)", QuoteCategory.AYET_HADIS),
        MotivationQuote(35, "İlim talep ediniz; çünkü onun tahsili hasenedir, mütalaası tesbihtir, araştırması cihattır.", "Muaz b. Cebel (r.a.)", QuoteCategory.AYET_HADIS),
        MotivationQuote(36, "Güzel soru sormak ilmin yarısıdır.", "Hadis-i Şerif (Taberânî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(37, "İlim talebi yolunda sabahlayan kimse, dönünceye kadar Allah yolundadır.", "Hadis-i Şerif (Tirmizî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(38, "İlim ancak öğrenmekle, hilim (yumuşak huyluluk) ancak gayretle elde edilir.", "Hadis-i Şerif (Taberânî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(39, "En hayırlınız Kur'an'ı öğrenen ve öğretendir.", "Hadis-i Şerif (Buhârî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(40, "Allah'ım, bana öğrettiğin ilimle beni faydalandır ve bana fayda verecek ilmi öğret.", "Hadis-i Şerif (Tirmizî)", QuoteCategory.AYET_HADIS),
        MotivationQuote(41, "Kişi bilmediğinin düşmanıdır; öğrenen kalbini selamete erdirir.", "Hz. Ali (k.v.)", QuoteCategory.AYET_HADIS),
        MotivationQuote(42, "Bana bir harf öğretenin kırk yıl kölesi olurum.", "Hz. Ali (k.v.)", QuoteCategory.AYET_HADIS),
        MotivationQuote(43, "İlim meclislerinde bulunmak bin rekat nafile namazdan faziletlidir.", "İbn Abbas (r.a.)", QuoteCategory.AYET_HADIS),
        MotivationQuote(44, "İlim göğüslerdeki cehalet karanlığını aydınlatan kandildir.", "İbn Mes'ud (r.a.)", QuoteCategory.AYET_HADIS),
        MotivationQuote(45, "Akıl gibi zenginlik, cehalet gibi fakirlik, edeb gibi miras yoktur.", "Hz. Ali (k.v.)", QuoteCategory.AYET_HADIS),

        // === 46-130: BÜYÜK İSLAM ALİMLERİNİN SÖZLERİ ===
        MotivationQuote(46, "Kardeşim! İlme ancak şu altı şeyle ulaşırsın: Zeka, hırs, sabır, yeterli nafaka, hocanın rehberliği ve uzun zaman.", "İmam Şâfiî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(47, "Kitaplarını yanında taşımayanın ilmi evde kalır; zihninde taşımayanın ilmi kaybolur.", "İmam Şâfiî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(48, "Kim ilmin zahmetine bir müddet katlanmazsa, ömrü boyunca cehaletin zilletini yudumlar.", "İmam Şâfiî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(49, "Her ne zaman bir meseleyi öğrenip cehaletimden kurtulsam, bilmediğim şeylerin ne kadar çok olduğunu anlarım.", "İmam Şâfiî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(50, "İlim, ezberlenen şey değil; kendisinden faydalanılan ve ahlaka yansıyan nurdur.", "İmam Şâfiî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(51, "Geceleri ilim mütalaasıyla uykusuz kalmak, bana en tatlı lezzetlerden daha sevimlidir.", "İmam Şâfiî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(52, "Kalp ilim ve hikmetle yaşar; ilimden üç gün mahrum kalan kalp manen ölür.", "İmam Gazzâlî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(53, "Amelsiz ilim delilik, ilimsiz amel ise batıldır.", "İmam Gazzâlî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(54, "Şüphe gerçeğe ulaştıran basamaktır. Şüphe etmeyen düşünemez, düşünmeyen gerçeği bulamaz.", "İmam Gazzâlî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(55, "Kendini bilmeyen, başkasının ilmini nasıl anlayabilir?", "İmam Gazzâlî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(56, "İlmin ilk adımı sükut, ikincisi dinlemek, üçüncüsü ezberlemek, dördüncüsü amel etmek, beşincisi ise yaymaktır.", "İmam Gazzâlî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(57, "Zamanını ilme vermeyenin ömrü zayi olmuştur.", "İmam Gazzâlî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(58, "Alim odur ki, ilmi onu dünyadan soğutsun ve ahirete meylettirsin.", "İmam Gazzâlî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(59, "İlim çok rivayet etmek değildir; ilim Allah'tan hakkıyla haşyet duymaktır.", "İmam Mâlik", QuoteCategory.ALIMLERDEN),
        MotivationQuote(60, "Bilmiyorum demek ilmin yarısıdır.", "İmam Mâlik", QuoteCategory.ALIMLERDEN),
        MotivationQuote(61, "İlim nurlu bir cevherdir; onu ancak arınmış ve temiz kalpler muhafaza edebilir.", "İmam Mâlik", QuoteCategory.ALIMLERDEN),
        MotivationQuote(62, "Mücadele ve cedel, ilmin nurunu kalpten söndürür.", "İmam Mâlik", QuoteCategory.ALIMLERDEN),
        MotivationQuote(63, "Kişi ilim talep ettiği müddetçe alimdir; 'ben artık bildim' dediği an cahil kalmıştır.", "İbn Mübârek", QuoteCategory.ALIMLERDEN),
        MotivationQuote(64, "Biz ilimden önce edebi öğrenmeye otuz yıl, ilme ise yirmi yıl harcadık.", "İbn Mübârek", QuoteCategory.ALIMLERDEN),
        MotivationQuote(65, "İsnad dindendir; eğer isnad olmasaydı herkes aklına eseni söylerdi.", "İbn Mübârek", QuoteCategory.ALIMLERDEN),
        MotivationQuote(66, "Görüşümüz bir re'ydir; bizden daha güzelini getirenin sözü başımızın tacıdır.", "İmam Ebû Hanîfe", QuoteCategory.ALIMLERDEN),
        MotivationQuote(67, "Fıkıh, kişinin nefsinin lehinde ve aleyhinde olan şeyleri bilmesidir.", "İmam Ebû Hanîfe", QuoteCategory.ALIMLERDEN),
        MotivationQuote(68, "İlmi ancak ciddiyet, gece uykusuzluğu ve samimi niyetle kazandık.", "İmam Ebû Hanîfe", QuoteCategory.ALIMLERDEN),
        MotivationQuote(69, "İlim tahsili nafile ibadetten hayırlıdır.", "İmam Ebû Hanîfe", QuoteCategory.ALIMLERDEN),
        MotivationQuote(70, "Hokka ve divitle mezara kadar beraber olacağız.", "İmam Ahmed b. Hanbel", QuoteCategory.ALIMLERDEN),
        MotivationQuote(71, "İnsanların ilme olan ihtiyacı, ekmek ve sudan daha fazladır; çünkü günde bir-iki defa ekmeğe, her an ise ilme muhtaçtır.", "İmam Ahmed b. Hanbel", QuoteCategory.ALIMLERDEN),
        MotivationQuote(72, "Sabır ilmin binitidir; sabırsız talebe yolda kalır.", "İmam Ahmed b. Hanbel", QuoteCategory.ALIMLERDEN),
        MotivationQuote(73, "Coğrafya kaderdir; tarih ise milletlerin hafızasıdır.", "İbn Haldûn", QuoteCategory.ALIMLERDEN),
        MotivationQuote(74, "Fazla sertlik talebeyi tembelliğe ve yalana iter; muhabbet ve hikmetle öğretiniz.", "İbn Haldûn", QuoteCategory.ALIMLERDEN),
        MotivationQuote(75, "İlim ehli devletlerin zenginliği ve adalet temelidir.", "İbn Haldûn", QuoteCategory.ALIMLERDEN),
        MotivationQuote(76, "Gözlem ve tecrübeye dayanmayan bilgi zan ve tahminden ibarettir.", "İbn Haldûn", QuoteCategory.ALIMLERDEN),
        MotivationQuote(77, "Hakikat birdir, akıl ve vahiy asla birbiriyle çelişmez; çelişki gibi görünen yorum noksanlığıdır.", "İbn Rüşd", QuoteCategory.ALIMLERDEN),
        MotivationQuote(78, "Felsefe, varlıkları düşünmek ve onların yaratıcısına delaletlerini araştırmaktır.", "İbn Rüşd", QuoteCategory.ALIMLERDEN),
        MotivationQuote(79, "Cehalet korkuyu, korku nefreti, nefret ise şiddeti doğurur.", "İbn Rüşd", QuoteCategory.ALIMLERDEN),
        MotivationQuote(80, "Tıp sanatını icra ederken hastanın ruhunu tedavi etmeyen tabip eksiktir.", "İbn Sînâ", QuoteCategory.ALIMLERDEN),
        MotivationQuote(81, "Dünyada hiçbir şey tesadüf değildir; her neticenin bir ilmi sebebi vardır.", "İbn Sînâ", QuoteCategory.ALIMLERDEN),
        MotivationQuote(82, "Alet ilimlerini (Mantık, Dil) kavramadan yüksek ilimlere soyunmak temelsiz bina yapmaya benzer.", "Fârâbî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(83, "Erdemli şehir (el-Medînetü'l-Fâzıla), ilim ve adalet üzere tesis edilir.", "Fârâbî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(84, "Kelimelerin manasını bilmeyen, fikirlerin derinliğini kavrayamaz.", "Fârâbî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(85, "Doğruyu söylemekten korkma; zira hakikat en sağlam kaledir.", "Fârâbî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(86, "Gözlem yapmadan kanun koyan tabip yahut mühendis felaket getirir.", "Bîrûnî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(87, "Hakikati arayan kimse, kendi nefsani taraftarlığını bir kenara bırakmalıdır.", "Bîrûnî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(88, "İlim sınır tanımaz; Doğu'nun ve Batı'nın hikmeti insanlığın ortak mirasıdır.", "Bîrûnî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(89, "Optik ilmi gözün aldanışlarını aklın ölçüsüyle tashih etmektir.", "İbnü'l-Heysem", QuoteCategory.ALIMLERDEN),
        MotivationQuote(90, "Önceki alimlerin kitaplarını okurken eleştirel gözle bak; delili olmayan iddiayı kabul etme.", "İbnü'l-Heysem", QuoteCategory.ALIMLERDEN),
        MotivationQuote(91, "İlmin başı sabır, ortası tefekkür, sonu ise teslimiyettir.", "Hasan-ı Basrî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(92, "Ey insanoğlu! Sen ancak günlerden ibaretsin; bir günün geçtiğinde bir parçan gitmiştir.", "Hasan-ı Basrî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(93, "İlim amel edilmek için aranır; amelsiz ilim yüktür.", "Süfyân-ı Sevrî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(94, "İlmi aramakta en büyük yardımcı az uyumak ve çok mütalaa etmektir.", "Süfyân-ı Sevrî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(95, "Hadis meclisleri cennet bahçeleridir.", "Süfyân b. Uyeyne", QuoteCategory.ALIMLERDEN),
        MotivationQuote(96, "İlmin meyvesi kalp yumuşaklığı ve tevazudur.", "Fudayl b. İyâz", QuoteCategory.ALIMLERDEN),
        MotivationQuote(97, "Gecenin karanlığında lambanın ışığında satır okumak cihan saltanatına bedeldir.", "Zemahşerî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(98, "Arap lisanının inceliklerine vakıf olmayan, Kur'an'ın mucizevi belagatini tadamaz.", "Zemahşerî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(99, "Lafızlar kabuk, manalar ise özdür; öze ulaşamayan kabukla oyalanır.", "Fahreddin er-Râzî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(100, "Akıl delilleriyle vahyin nuru birleştiğinde hakikat güneş gibi parlar.", "Fahreddin er-Râzî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(101, "Talebenin hocasına hürmeti, ilimden istifadesinin anahtarıdır.", "Burhâneddin ez-Zernûcî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(102, "Niyeti halis olmayan talebenin ilmi bereketsiz kalır.", "Burhâneddin ez-Zernûcî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(103, "Dersleri tekrar etmek (müzakere), yeni metin ezberlemekten daha mühimdir.", "Burhâneddin ez-Zernûcî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(104, "Kitap ödünç vermekten çekinmeyiniz; ilmin zekatı cömertliktir.", "İbn Abdilberr", QuoteCategory.ALIMLERDEN),
        MotivationQuote(105, "Alim hata ettiğinde onu edeple ikaz ediniz, zemmetmeyiniz.", "İbn Abdilberr", QuoteCategory.ALIMLERDEN),
        MotivationQuote(106, "İlim tahsilinde utanmak ve kibirlenmek iki büyük engeldir.", "Mücâhid b. Cebr", QuoteCategory.ALIMLERDEN),
        MotivationQuote(107, "Cahil cesur olur; alim ise delil aramadan adım atmaz.", "Katâde", QuoteCategory.ALIMLERDEN),
        MotivationQuote(108, "Her ilim dalının bir usulü vardır; usulsüz vusul (ulaşma) olmaz.", "Usûlcülerin Kaidesi", QuoteCategory.ALIMLERDEN),
        MotivationQuote(109, "Şartlar değişince hükümlerin değişmesi inkar olunamaz.", "Mecelle, Madde 39", QuoteCategory.ALIMLERDEN),
        MotivationQuote(110, "Zarar ve mukabele-i bizzarar yoktur; adalet ilmin gayesidir.", "Mecelle Kaidesi", QuoteCategory.ALIMLERDEN),
        MotivationQuote(111, "Bir meselenin illeti bilinmedikçe kıyas yapılamaz.", "İmam el-Cüveynî", QuoteCategory.ALIMLERDEN),
