        MotivationQuote(113, "Metin tenkidi yapılmadan sadece isnada güvenmek nakilcilik hatasıdır.", "İbn Kayyim el-Cevziyye", QuoteCategory.ALIMLERDEN),
        MotivationQuote(114, "Kalp iki sevgiyle dolmaz; dünyaya aşık olan ilmin lezzetini tadamaz.", "İbn Kayyim el-Cevziyye", QuoteCategory.ALIMLERDEN),
        MotivationQuote(115, "Sabır iki kısımdır: Zorluklara katlanmak ve günahlardan kaçınmak. İlim her ikisini de gerektirir.", "İbn Teymiyye", QuoteCategory.ALIMLERDEN),
        MotivationQuote(116, "Akl-ı selim ile nakl-i sarih asla tenakuza düşmez.", "İbn Teymiyye", QuoteCategory.ALIMLERDEN),
        MotivationQuote(117, "Kitapları hıfzeden değil, kitaptaki hikmeti ameline nakşeden fakihtir.", "İmam Nevevî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(118, "Günde bir hadis ezberleyip hayatına tatbik eden, on yılda derya olur.", "İmam Nevevî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(119, "İlim taliplerine şefkat göstermek ulemanın borcudur.", "İmam Nevevî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(120, "Zaman kılıç gibidir; sen onu kesmezsen o seni keser.", "İmam Şâfiî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(121, "İlmin kapısı hüsn-ü niyet, penceresi tefekkürdür.", "Cüneyd-i Bağdâdî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(122, "Her gün bir satır yazan, seneler sonra kütüphaneler dolusu eser bırakır.", "Kâtip Çelebi", QuoteCategory.ALIMLERDEN),
        MotivationQuote(123, "Cehalet en büyük düşmandır; ilimle donanmayan zihin safsataya kanar.", "Kâtip Çelebi", QuoteCategory.ALIMLERDEN),
        MotivationQuote(124, "Akıl ve nakil mizanında tartılmayan fikir rüzgarda savrulan yapraktır.", "İsmail Hakkı Bursevî", QuoteCategory.ALIMLERDEN),
        MotivationQuote(125, "Âlimin uykusu cahilin ibadetinden evladır; zira o uyurken de tefekkür eder.", "Süfyân-ı Sevrî", QuoteCategory.ALIMLERDEN),
